begin;
select plan(26);
select has_function('public','claim_ai_turn',array['uuid','text','uuid','uuid']);
insert into auth.users(id) values('09090909-0000-0000-0000-000000000040'),('09090909-0000-0000-0000-000000000041');
insert into public.profiles(user_id) values('09090909-0000-0000-0000-000000000040'),('09090909-0000-0000-0000-000000000041');
insert into public.consents(user_id,consent_version,choice,text_sha256,locale)
values('09090909-0000-0000-0000-000000000040','test','granted','test','en'),('09090909-0000-0000-0000-000000000041','test','granted','test','en');
select set_config('request.jwt.claim.sub','09090909-0000-0000-0000-000000000040',true);
set local role authenticated;
select is(public.claim_ai_turn('09090909-0000-0000-0000-000000000042','same',null,'09090909-0000-0000-0000-000000000043')->>'status','claimed','first execution owns lease');
select is(public.claim_ai_turn('09090909-0000-0000-0000-000000000042','same',null,'09090909-0000-0000-0000-000000000043')->>'status','claimed','same lease can confirm ownership');
select is(public.claim_ai_turn('09090909-0000-0000-0000-000000000042','same',null,'09090909-0000-0000-0000-000000000044')->>'status','busy','different active lease cannot execute twice');
select ok((public.claim_ai_turn('09090909-0000-0000-0000-000000000042','same',null,'09090909-0000-0000-0000-000000000044')->>'retry_after')::int between 1 and 90,'busy reports bounded retry delay');
select throws_ok($$select public.claim_ai_turn('09090909-0000-0000-0000-000000000042','changed',null,'09090909-0000-0000-0000-000000000044')$$,'23505','TURN_CONFLICT','same turn cannot change payload');
select is(public.release_ai_turn('09090909-0000-0000-0000-000000000042','09090909-0000-0000-0000-000000000044'),false,'wrong token cannot release');
reset role;
select set_config('request.jwt.claim.sub','09090909-0000-0000-0000-000000000041',true);
set local role authenticated;
select throws_ok($$select public.claim_ai_turn('09090909-0000-0000-0000-000000000042','same',null,'09090909-0000-0000-0000-000000000043')$$,'23505','TURN_CONFLICT','another account cannot acquire owned turn');
select is(public.release_ai_turn('09090909-0000-0000-0000-000000000042','09090909-0000-0000-0000-000000000043'),false,'another account cannot release owned turn');
reset role;
update nb.ai_turn_leases set expires_at=clock_timestamp()-interval '1 second' where turn_id='09090909-0000-0000-0000-000000000042';
select set_config('request.jwt.claim.sub','09090909-0000-0000-0000-000000000040',true);
set local role authenticated;
select throws_ok($$select public.record_claimed_ai_turn('09090909-0000-0000-0000-000000000043','09090909-0000-0000-0000-000000000042','same','{"sentence":"late"}','[]',100,'test',null,null)$$,'55000','TURN_LEASE_LOST','expired executor cannot publish even without replacement');
select is(public.claim_ai_turn('09090909-0000-0000-0000-000000000042','same',null,'09090909-0000-0000-0000-000000000044')->>'status','claimed','expired matching request can recover execution');
select is(public.release_ai_turn('09090909-0000-0000-0000-000000000042','09090909-0000-0000-0000-000000000043'),false,'expired owner cannot release replacement');
select throws_ok($$select public.record_claimed_ai_turn('09090909-0000-0000-0000-000000000043','09090909-0000-0000-0000-000000000042','same','{"sentence":"stale"}','[]',100,'test',null,null)$$,'55000','TURN_LEASE_LOST','expired replaced executor cannot publish');
select throws_ok($$select public.record_claimed_ai_turn('09090909-0000-0000-0000-000000000044','09090909-0000-0000-0000-000000000042','changed','{"sentence":"changed"}','[]',100,'test',null,null)$$,'23505','TURN_CONFLICT','live executor cannot change claimed payload');
select is((public.record_claimed_ai_turn('09090909-0000-0000-0000-000000000044','09090909-0000-0000-0000-000000000042','same','{"sentence":"ok"}','[]',100,'test',null,null)->>'replay')::boolean,false,'current lease publishes durable result');
select is((public.record_claimed_ai_turn('09090909-0000-0000-0000-000000000043','09090909-0000-0000-0000-000000000042','same','{"sentence":"unused"}','[]',100,'test',null,null)->>'replay')::boolean,true,'completed exact receipt replays without active lease');
select is(public.claim_ai_turn('09090909-0000-0000-0000-000000000042','same',null,'09090909-0000-0000-0000-000000000045')->>'status','replay','completed exact request replays without model execution');
select throws_ok($$select public.claim_ai_turn('09090909-0000-0000-0000-000000000042','changed',null,'09090909-0000-0000-0000-000000000045')$$,'23505','TURN_CONFLICT','completed turn still binds payload');
select throws_ok($$select public.record_claimed_ai_turn('09090909-0000-0000-0000-000000000043','09090909-0000-0000-0000-000000000042','changed','{"sentence":"late"}','[]',100,'test',null,null)$$,'23505','TURN_CONFLICT','completed publication replay validates original payload');
select is(public.release_ai_turn('09090909-0000-0000-0000-000000000042','09090909-0000-0000-0000-000000000044'),true,'matching owner releases');
reset role;
insert into nb.ai_turn_leases(turn_id,user_id,lease_id,request_hash,expires_at)
select md5('expired-turn-'||i)::uuid,'09090909-0000-0000-0000-000000000040','09090909-0000-0000-0000-000000000050',repeat('a',64),clock_timestamp()-interval '2 days' from generate_series(1,205) i;
set local role authenticated;
select public.claim_ai_turn('09090909-0000-0000-0000-000000000048','cleanup',null,'09090909-0000-0000-0000-000000000049');
reset role;
select is((select count(*)::int from nb.ai_turn_leases where lease_id='09090909-0000-0000-0000-000000000050'),105,'cleanup removes at most100 old rows per admission');
insert into public.consents(user_id,consent_version,choice,text_sha256,locale,decided_at)
values('09090909-0000-0000-0000-000000000040','test','withdrawn','test','en',now()+interval '1 second');
set local role authenticated;
select throws_ok($$select public.claim_ai_turn('09090909-0000-0000-0000-000000000046','same',null,'09090909-0000-0000-0000-000000000043')$$,'42501','CONSENT_WITHDRAWN','withdrawn account cannot start model');
reset role;
select ok(not has_table_privilege('authenticated','nb.ai_turn_leases','INSERT'),'no direct lease writes');
select ok(not has_function_privilege('anon','public.claim_ai_turn(uuid,text,uuid,uuid)','EXECUTE'),'anonymous cannot claim');
update public.profiles set deletion_requested_at=now() where user_id='09090909-0000-0000-0000-000000000041';
select set_config('request.jwt.claim.sub','09090909-0000-0000-0000-000000000041',true);
set local role authenticated;
select throws_ok($$select public.claim_ai_turn('09090909-0000-0000-0000-000000000047','same',null,'09090909-0000-0000-0000-000000000043')$$,'42501','ACCOUNT_DELETING','deleting account cannot start model');
reset role;
delete from auth.users where id='09090909-0000-0000-0000-000000000040';
select is((select count(*)::int from nb.ai_turn_leases where user_id='09090909-0000-0000-0000-000000000040'),0,'account deletion cascades active and expired leases');
select * from finish();
rollback;
